const EVOLUTION = 'http://evolution-api:8080';
const EVO_KEY = 'SUBSTITUA_PELA_EVOLUTION_API_KEY';
const INSTANCE = 'principal';
const CRM = 'http://lovet-crm:3000';
const WA_TOKEN = 'SUBSTITUA_PELO_WA_API_TOKEN';
const H_CRM = { 'Content-Type': 'application/json', 'x-webhook-token': WA_TOKEN };
const H_EVO = { 'Content-Type': 'application/json', apikey: EVO_KEY };

const http = async (o) => this.helpers.httpRequest(o);
const res = await http({ method: 'GET', url: CRM + '/api/wa/birthdays', headers: H_CRM });
const items = res.items || [];
const out = [];
for (const it of items) {
  const first = String(it.name || '').split(' ')[0] || 'você';
  const msg = 'Feliz aniversário, ' + first + '! 🎉 A equipe da Lovet Distribuidora deseja um dia incrível pra você. Qualquer coisa que precisar, é só chamar por aqui 😊';
  try {
    const sent = await http({ method: 'POST', url: EVOLUTION + '/message/sendText/' + INSTANCE, headers: H_EVO, body: { number: it.phone, text: msg } });
    await http({ method: 'POST', url: CRM + '/api/wa/birthday-sent', headers: H_CRM, body: { contactId: it.contactId } });
    out.push({ json: { phone: it.phone, msg, sent: true } });
  } catch (e) {
    out.push({ json: { phone: it.phone, error: String(e) } });
  }
  await new Promise(r => setTimeout(r, 4000));
}
return out.length ? out : [{ json: { note: 'sem aniversariantes hoje' } }];
